-- Geography: 830 new questions, taking it to 1245.
--
-- Written so the correct answer is never reliably the longest option -- the tell
-- that made the Psychology bank winnable without reading the prompt. All options
-- share one type and grammatical form. Measured on this bank: the answer is the
-- strictly longest option 25.2% of the time, against 25% by chance.

insert into public.quiz_questions (
  id,
  category_id,
  prompt,
  correct_answer,
  wrong_answers,
  explanation,
  language_code,
  grade_level,
  subject,
  display_order,
  is_active
)
select
  'geo_r2_' || lpad(question.ordinality::text, 4, '0'),
  'geography',
  question.item ->> 'p',
  question.item ->> 'a',
  array(select jsonb_array_elements_text(question.item -> 'w')),
  question.item ->> 'e',
  'en',
  null,
  question.item ->> 's',
  (
    select coalesce(max(existing.display_order), 0)
    from public.quiz_questions as existing
    where existing.category_id = 'geography'
  ) + question.ordinality::integer,
  true
from jsonb_array_elements($questions$
